import pty, os, sys
def run(args, inp):
    pid, fd = pty.fork()
    if pid == 0:
        os.execv('/workspace/executable', ['/workspace/executable']+args)
    else:
        out=b''
        try:
            os.write(fd, inp)
            while True:
                try:
                    d=os.read(fd,4096)
                except OSError:
                    break
                if not d: break
                out+=d
        finally:
            os.waitpid(pid,0)
        sys.stdout.buffer.write(out)
