import pty, os, sys
def run(args, inp, env=None):
    pid, fd = pty.fork()
    if pid == 0:
        if env: os.environ.update(env)
        os.execv('/workspace/executable', ['/workspace/executable']+args)
    else:
        out=b''
        try:
            os.write(fd, inp)
            while True:
                try:
                    d=os.read(fd,4096)
                except OSError:
                    break
                if not d: break
                out+=d
        finally:
            os.waitpid(pid,0)
        sys.stdout.buffer.write(out)
run(['-c'], b'{\"a\":1}\n', {'TERM':'xterm-256color'})
print()
print('=== no -c, pty, TERM=xterm ===')
run([], b'{\"a\":1}\n', {'TERM':'xterm'})
" | od -c

